package pe.animetv;
import java.util.*;import androidx.media3.common.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.RobolectricTestRunner;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
public class PlaybackCompatibilityTest {
    @Test public void excludedFileDoesNotHideHostOtherEpisodesOrDubAndExpires(){android.content.Context context=org.robolectric.RuntimeEnvironment.getApplication();context.getSharedPreferences("incompatible-video",0).edit().clear().commit();VideoExclusions exclusions=new VideoExclusions(context);pe.animetv.Models.Server s=new pe.animetv.Models.Server("MP4Upload","https://example.test/video","SUB");exclusions.block(s,"episode-1",1000);assertTrue(new VideoExclusions(context).blocked(s,"episode-1",1001));assertFalse(exclusions.blocked(s,"episode-2",1001));assertFalse(exclusions.blocked(new pe.animetv.Models.Server(s.name(),s.url(),"LAT"),"episode-1",1001));assertFalse(exclusions.blocked(s,"episode-1",86401001));}
    private Tracks tracks(String mime,boolean selected){Format format=new Format.Builder().setSampleMimeType(mime).setWidth(1920).setHeight(1080).build();return new Tracks(List.of(new Tracks.Group(new TrackGroup(format),false,new int[]{C.FORMAT_HANDLED},new boolean[]{selected})));}
    @Test public void h264HlsIsNotHiddenBecauseTvLacksAv1(){assertFalse(VideoCompatibility.unsupportedAv1(tracks(MimeTypes.VIDEO_H264,true),f->false));assertFalse(VideoCompatibility.unsupportedAv1(tracks(MimeTypes.VIDEO_AV1,false),f->false));}
    @Test public void selectedAv1RequiresHardwareForItsActualFormat(){assertTrue(VideoCompatibility.unsupportedAv1(tracks(MimeTypes.VIDEO_AV1,true),f->false));assertFalse(VideoCompatibility.unsupportedAv1(tracks(MimeTypes.VIDEO_AV1,true),f->f.width==1920&&f.height==1080));}
    @Test public void highBitrateBuffersHaveMoreRunwayAndBoundedRam(){for(String server:List.of("Desu","Magi","MP4Upload","HLS")){PlaybackBufferPolicy b=PlaybackBufferPolicy.forStream(server,server.equals("MP4Upload")?"video/mp4":"application/x-mpegURL");assertTrue(b.start()>=8000);assertTrue(b.rebuffer()>=b.start());assertTrue(b.minimum()>=b.rebuffer());assertTrue(b.maximum()>=b.minimum());assertTrue(b.bytes()<=48*1024*1024);}assertEquals(1000,PlaybackBufferPolicy.forStream("Voe","application/x-mpegURL").start());}
    @Test public void jkReplicaPolicyCoversBothPublishedPathFamilies(){String ref="https://jkanime.net/jkplayer/um";assertTrue(JkCdnInterceptor.eligible(new okhttp3.Request.Builder().url("https://cdn4.ducvomes.com/jp/segs/a/video.ts").header("Referer",ref).build()));}
}
